import { APIPage, type APIPageProps } from "../../components/api-reference";
import prepared from "../../../../../apps/web/src/generated/course-api.json";

const snapshot = prepared as unknown as {
  preloaded: APIPageProps["preloaded"];
  pages: Record<string, Omit<APIPageProps, "preloaded">>;
};

/** Story data is generated by the same Elysia/Fumadocs pipeline as production docs. */
export function APIPageFixture({ page }: { page: string }) {
  const options = snapshot.pages[page];
  if (!options) throw new Error(`Missing generated API story page: ${page}.`);
  return <APIPage {...options} preloaded={snapshot.preloaded} />;
}
